"""
Pydantic schemas for Interview Question Bank.
"""

from typing import Any
from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class AIQuestionItemPayload(BaseModel):
    """Schema for individual question generated by AI."""

    model_config = ConfigDict(populate_by_name=True)

    question: str = Field(default="", alias="question_text")
    category: str = "Technical"
    difficulty: str = "Medium"
    role: str = "Software Engineer"
    tags: list[str] = Field(default_factory=list)
    explanation: str | None = None

    @model_validator(mode="before")
    @classmethod
    def normalize_fields(cls, data: Any) -> Any:
        if isinstance(data, dict):
            # Extract question text from multiple possible keys
            q = (
                data.get("question")
                or data.get("question_text")
                or data.get("text")
                or data.get("title")
                or data.get("prompt")
                or ""
            )
            data["question"] = str(q).strip()

            # Extract explanation from multiple possible keys
            expl = (
                data.get("explanation")
                or data.get("answer")
                or data.get("solution")
                or data.get("answer_guide")
                or data.get("sample_answer")
            )
            if isinstance(expl, list):
                expl = "\n".join(f"• {item}" for item in expl)
            data["explanation"] = str(expl).strip() if expl else None

            # Normalize tags
            tags = data.get("tags")
            if isinstance(tags, str):
                data["tags"] = [t.strip() for t in tags.split(",") if t.strip()]
            elif not isinstance(tags, list):
                data["tags"] = []
        return data


class AIGeneratedQuestionsPayload(BaseModel):
    """Schema for batch AI question generation output."""

    questions: list[AIQuestionItemPayload] = Field(default_factory=list)


class GenerateQuestionsRequest(BaseModel):
    """Request payload to generate AI practice questions."""

    topic: str | None = Field(None, description="Optional specific topic (e.g. System Design, React hooks)")
    category: str = Field("Technical", description="Technical, HR, Behavioral, Coding, DSA, SQL, Aptitude, Role-specific")
    difficulty: str = Field("Medium", description="Easy, Medium, Hard")
    role: str = Field("Software Engineer", description="Target job role")
    count: int = Field(5, ge=1, le=25, description="Number of questions to generate (up to 25)")



class QuestionResponse(BaseModel):
    """Interview question response schema."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    question: str
    category: str
    difficulty: str
    role: str
    tags: list[str] = Field(default_factory=list)
    source_type: str = "standard"
    source_label: str = "Standard Interview Question"
    explanation: str | None = None
    is_saved: bool = False
    created_at: datetime
